WITH joined AS ( SELECT sr.sr_return_amt, ca.ca_state, hd.hd_income_band_sk, hd.hd_buy_potential, i.i_brand FROM store_returns sr JOIN customer_address ca ON sr.sr_addr_sk = ca.ca_address_sk JOIN household_demographics hd ON sr.sr_hdemo_sk = hd.hd_demo_sk JOIN item i ON sr.sr_item_sk = i.i_item_sk ), state_income_stats AS ( SELECT ca_state, hd_income_band_sk, AVG(sr_return_amt) AS avg_return_amt, SUM(sr_return_amt) AS total_return_amt, COUNT(*) AS cnt_returns FROM joined GROUP BY ca_state, hd_income_band_sk ) SELECT ca_state, hd_income_band_sk, avg_return_amt, total_return_amt, cnt_returns, CASE WHEN avg_return_amt > 200 THEN 'HIGH_AVG' WHEN avg_return_amt BETWEEN 100 AND 200 THEN 'MID_AVG' ELSE 'LOW_AVG' END AS avg_return_category, PERCENT_RANK() OVER (ORDER BY avg_return_amt) AS avg_return_percentile, NTILE(4) OVER (ORDER BY total_return_amt DESC) AS total_return_quartile, LAG(avg_return_amt) OVER (PARTITION BY ca_state ORDER BY hd_income_band_sk) AS prev_state_avg, avg_return_amt - LAG(avg_return_amt) OVER (PARTITION BY ca_state ORDER BY hd_income_band_sk) AS avg_return_diff FROM state_income_stats WHERE cnt_returns > 10 ORDER BY ca_state, hd_income_band_sk
